"""Grade the published slate files against the recorded adjudication."""
from rewardkit import criteria, criterion

import base64
import configparser
import csv
import datetime as dt
import hashlib
import io
import json
import os
import pathlib
import re
import tarfile
import tempfile
import zlib

FORMATS = ['classic', 'singleton', 'relic']
VERDICTS = ['seated', 'amended', 'flagged', 'barred', 'unresolved']
REASONS = ['card_barred', 'chain_cycle', 'charge_cycle', 'copy_breach',
           'no_prior_list', 'points_over', 'tier_bar', 'unknown_printing']
SOURCES = ['addendum', 'base', 'global', 'rider']
TIERS = ['barred', 'caution', 'clear', 'probation']

LANE = re.compile(r"^(\S+) host=(\S+) receipt=(\S+) submission=(\S+) lane=(\S+)")


def stamp_of(unit):
    return unit.strftime("%Y-%m-%dT%H:%M:%SZ")


def day_label(moment):
    return moment.strftime("%Y-%m-%d")


def utc_of(text):
    body = text.strip()
    if body.endswith("Z"):
        body = body[:-1]
    return dt.datetime.strptime(body, "%Y-%m-%dT%H:%M:%S").replace(
        tzinfo=dt.timezone.utc)


class Slate(object):
    """The corpus facts the cheat probes read, parsed straight from the feeds."""


def receipts_of(root, S):
    S.receipts = {}
    for leaf in ("intake_journal.log.1", "intake_journal.log"):
        standing = None
        with open(os.path.join(root, leaf)) as fh:
            for raw in fh:
                row = raw.rstrip("\n")
                if row.startswith("    "):
                    if standing is not None:
                        for piece in row.split():
                            if piece.startswith("recorded_override="):
                                standing["override"] = utc_of(piece.split("=", 1)[1])
                    continue
                hit = LANE.match(row)
                if hit is None:
                    standing = None
                    continue
                standing = {"raw": utc_of(hit.group(1)), "host": hit.group(2),
                            "rc": hit.group(3), "override": None}
                S.receipts.setdefault(hit.group(4), []).append(standing)


def slate_facts(root):
    S = Slate()
    book = configparser.ConfigParser()
    book.read(os.path.join(root, "slate_window.ini"))
    S.open_stage = book.get("slate", "open_stage")
    S.base_cutoff = utc_of(book.get("slate", "legality_cutoff"))
    S.headers = []
    for leaf in sorted(os.listdir(root)):
        if leaf.startswith("entry_header_") and leaf.endswith(".csv"):
            with open(os.path.join(root, leaf), newline="") as fh:
                for row in csv.reader(fh):
                    if len(row) > 1 and row[0] != "submission_id":
                        S.headers.append({"sid": row[0]})
    S.legacy = []
    with open(os.path.join(root, "legacy_entries.tsv"), newline="") as fh:
        for row in csv.DictReader(fh, delimiter="\t"):
            S.legacy.append({"sid": row["submission_id"], "season": row["season"]})
    S.hoff = {}
    with open(os.path.join(root, "host_clock_offsets.csv"), newline="") as fh:
        for row in csv.DictReader(fh):
            S.hoff[(row["host"], row["day"])] = int(row["offset_seconds"])
    receipts_of(root, S)
    return S


def sealed(root):
    parts = []
    for leaf in sorted(os.listdir(root)):
        with open(os.path.join(root, leaf), "rb") as fh:
            parts.append("%s %s" % (leaf, hashlib.sha256(fh.read()).hexdigest()))
    return hashlib.sha256("\n".join(parts).encode()).hexdigest()


def rebuild(root):
    fact = json.loads(zlib.decompress(base64.b64decode(_GOLD)).decode())
    if sealed(root) != fact["corpus"]:
        raise RuntimeError("the recorded adjudication does not belong to this corpus")
    fact["ctx"] = slate_facts(root)
    return fact


