ARTIFACTS = [
    "/app/out/final_state.json",
    "/app/out/report.json",
    "/app/out/scenario_alpha.json",
    "/app/out/scenario_beta.json",
    "/app/out/scenario_mode.json",
    "/app/out/transcript_summary.json",
    "/app/out/summary.json",
]

NAMES = [p.rsplit("/", 1)[1] for p in ARTIFACTS]

ADVICE_BUDGET_CPT = 1600

ENTRY_KEYS = ("submission_id", "player_id", "format", "venue", "effective_at",
              "recorded_at", "verdict", "reason_code", "points_total",
              "copy_breach_count", "carry_before", "carry_after", "tier",
              "governing_source", "channel")

STATE_KEYS = ("slate_id", "journal_seq", "digest", "entries", "refusals")

_HOME = []
_FACT = []


def _home():
    if _HOME:
        return _HOME[0]
    packed = zlib.decompress(base64.b64decode(_CORPUS))
    seat = tempfile.mkdtemp(prefix="slate-")
    with tarfile.open(fileobj=io.BytesIO(packed), mode="r:") as bundle:
        bundle.extractall(seat)
    _HOME.append(seat)
    return seat


def _facts():
    if _FACT:
        return _FACT[0]
    try:
        built = rebuild(_home())
    except Exception:
        built = {}
    _FACT.append(built)
    return built


def _file(workspace, name):
    try:
        spot = pathlib.Path(workspace) / "out" / name
        return json.loads(spot.read_text(encoding="utf-8"))
    except Exception:
        return None


def _raw(workspace, name):
    try:
        return (pathlib.Path(workspace) / "out" / name).read_text(
            encoding="utf-8", errors="replace")
    except Exception:
        return ""


def _list(doc, field):
    if not isinstance(doc, dict):
        return None
    seat = doc.get(field)
    if not isinstance(seat, list):
        return None
    for item in seat:
        if not isinstance(item, dict):
            return None
    return seat


def _column(seat, fields):
    return [tuple(line.get(f) for f in fields) for line in seat]


def _mine(workspace, fields):
    seat = _list(_file(workspace, "report.json"), "entries")
    if seat is None:
        return None
    return _column(seat, fields)


def _theirs(fields):
    book = _facts().get("report")
    if not isinstance(book, dict):
        return None
    return _column(book["entries"], fields)



def _budget_split(doc):
    budget = _facts().get("budgets")
    seat = _list(doc, "entries")
    if not budget or not seat:
        return None
    shelf = {}
    shown = set()
    published = set()
    advisory = set()
    for line in seat:
        mark = line.get("reason_code")
        if mark is not None and mark != "points_over":
            continue
        label = line.get("submission_id")
        total = line.get("points_total")
        shape = line.get("format")
        if not isinstance(label, str) or shape not in FORMATS:
            return None
        if isinstance(total, bool) or not isinstance(total, int):
            return None
        if shape not in shelf:
            shelf[shape] = budget[shape]
        if mark == "points_over":
            shown.add(label)
        if total > shelf[shape]:
            published.add(label)
        if total > ADVICE_BUDGET_CPT:
            advisory.add(label)
    return shown, published, advisory


def _late_receipts():
    S = _facts().get("ctx")
    if S is None:
        return {}
    cutoff = getattr(S, "base_cutoff", None)
    if cutoff is None:
        return {}
    shelf = {}
    for sub_key, lanes in S.receipts.items():
        honest = None
        drift = None
        for lane in lanes:
            if lane["override"] is not None:
                at = lane["override"]
            else:
                off = S.hoff.get((lane["host"], day_label(lane["raw"])), 0)
                at = lane["raw"] - dt.timedelta(seconds=off)
            if at <= cutoff and (honest is None or at < honest):
                honest = at
            bare = lane["raw"]
            if bare <= cutoff and (drift is None or bare > drift):
                drift = bare
        if honest is not None and drift is not None and drift != honest:
            shelf[sub_key] = stamp_of(drift)
    return shelf


def _record_sites():
    S = _facts().get("ctx")
    if S is None:
        return {}
    shelf = {}
    for ix in (1, 2, 3, 4):
        where = os.path.join(_home(), "entry_header_%02d.csv" % ix)
        if not os.path.exists(where):
            continue
        with open(where, "r", encoding="utf-8") as stream_fh:
            next(stream_fh, "")
            for line_text in stream_fh:
                chunks = line_text.rstrip("\n").split(",")
                if len(chunks) >= 6:
                    shelf[chunks[0]] = (chunks[3], chunks[5])
    return shelf


@criterion(description="Report lists exactly the slate submissions in the required order")
def report_entry_roster(workspace: pathlib.Path) -> bool:
    try:
        mine = _mine(workspace, ("submission_id",))
        theirs = _theirs(("submission_id",))
        return bool(theirs) and mine == theirs
    except Exception:
        return False


