@criterion(description="Every entry carries one service record, with the state map matching the drive and the report naming the same channel")
def final_state_entry_map(workspace: pathlib.Path) -> bool:
    try:
        mine = _file(workspace, "final_state.json")
        script = _facts().get("plan")
        if not isinstance(mine, dict) or script is None:
            return False
        shelf = mine.get("entries")
        if not isinstance(shelf, dict):
            return False
        want = script["state"]
        if sorted(shelf) != sorted(want):
            return False
        for slot_id, body in want.items():
            got = shelf.get(slot_id)
            if not isinstance(got, dict):
                return False
            for field in ("state", "scope", "channel", "last_seq"):
                if got.get(field) != body[field]:
                    return False
        book = _list(_file(workspace, "report.json"), "entries")
        if not book:
            return False
        for line in book:
            slot = shelf.get(line.get("submission_id"))
            if not isinstance(slot, dict):
                return False
            if line.get("channel") != slot.get("channel"):
                return False
        return True
    except Exception:
        return False


@criterion(description="Journal sequence and digest agree across both service artifacts and match an independent fold")
def journal_digest_identity(workspace: pathlib.Path) -> bool:
    try:
        live = _file(workspace, "final_state.json")
        drive = _file(workspace, "transcript_summary.json")
        script = _facts().get("plan")
        if not isinstance(live, dict) or not isinstance(drive, dict):
            return False
        if script is None:
            return False
        fold = hashlib.sha256(_facts()["report"]["slate_id"].encode()).hexdigest()
        for step in script["journal"]:
            tag = "%d:%s:%s:%s:%s" % (step["seq"], step["op"], step["entry"],
                                      step["scope"], step["channel"])
            fold = hashlib.sha256((fold + "|" + tag).encode()).hexdigest()
        ticket = script["seq"]
        return (live.get("journal_seq") == ticket
                and drive.get("journal_seq") == ticket
                and live.get("digest") == fold
                and drive.get("digest") == fold)
    except Exception:
        return False


